function useStorageState<T>(
  key: string,
  defaultValue: T,
  storageType: "localStorage" | "sessionStorage" = "localStorage"
): [T, (value: T) => void, () => void, (value: T) => void] {
  //in ssr, window doesn't exist, just use default
  const saved =
    typeof window !== "undefined" ? window[storageType].getItem(key) : null;
  const [_state, _setState] = useState<T>(
    saved !== null ? JSON.parse(saved) : defaultValue
  );
  const setState = useCallback(
    (value: T) => {
      if (value === undefined) {
        console.warn(`${key} can't be stored as undefined, casting to null.`);
      }
      const v = value === undefined ? null : value;
      if (typeof window !== "undefined") {
        window[storageType].setItem(key, JSON.stringify(v));
      }
      _setState(value);
    },
    [key, storageType]
  );
  const clearState = useCallback(() => {
    if (typeof window !== "undefined") {
      window[storageType].removeItem(key);
    }
  }, [key, storageType]);
  return [_state, setState, clearState, _setState];
}

export function usePersistedState<T>(
  key: string,
  defaultValue: T,
  storageType: "localStorage" | "sessionStorage" = "localStorage"
): [T, (value: T) => void] {
  const [state, setState] = useStorageState<T>(key, defaultValue, storageType);
  return [state, setState];
}

export function useSessionStorage<T>(
  key: string,
  defaultValue: T
): [T | undefined, (value: T) => void, () => void] {
  const [state, setState, clear, rawSet] = useStorageState<T | undefined>(
    key,
    defaultValue,
    "sessionStorage"
  );
  const clearState = useCallback(() => {
    clear();
    rawSet(undefined);
  }, [clear, rawSet]);
  return [state, setState, clearState];
}

